-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE "users" (
  "id" int NOT NULL AUTO_INCREMENT,
  "username" varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  "password" varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  "full_name" varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  "role" varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'USER',
  "oauth_provider" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "oauth_subject" varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "blocked" tinyint(1) DEFAULT '0',
  PRIMARY KEY ("id"),
  UNIQUE KEY "username" ("username"),
  UNIQUE KEY "ux_users_oauth" ("oauth_provider","oauth_subject")
);

-- Records of users

-- ----------------------------
-- Table structure for tours
-- ----------------------------
DROP TABLE IF EXISTS `tours`;
CREATE TABLE "tours" (
  "id" int NOT NULL AUTO_INCREMENT,
  "name" varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  "description" text COLLATE utf8mb4_unicode_ci,
  "price" double NOT NULL,
  "original_price" double DEFAULT '0',
  "available_seats" int NOT NULL,
  "start_date" date NOT NULL,
  "image_url" varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "origin" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "destination" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "duration" varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "discount_end_date" timestamp NULL DEFAULT NULL,
  "country" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Viß╗çt Nam',
  "status" varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'APPROVED',
  "approval_note" text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY ("id")
);

-- Records of tours

