-- Table structure for tour_itineraries
-- ----------------------------
DROP TABLE IF EXISTS `tour_itineraries`;
CREATE TABLE "tour_itineraries" (
  "id" int NOT NULL AUTO_INCREMENT,
  "tour_id" int NOT NULL,
  "day_number" int NOT NULL,
  "title" varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  "description" text COLLATE utf8mb4_unicode_ci NOT NULL,
  "meals" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'S├íng, Tr╞░a, Tß╗æi',
  "accommodation" varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Kh├ích sß║ín 4 sao ti├¬u chuß║⌐n',
  "transport" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Xe du lß╗ïch ─æß╗¥i mß╗¢i / M├íy bay',
  PRIMARY KEY ("id"),
  KEY "idx_tour_day" ("tour_id","day_number"),
  CONSTRAINT "tour_itineraries_ibfk_1" FOREIGN KEY ("tour_id") REFERENCES "tours" ("id") ON DELETE CASCADE
);

-- Records of tour_itineraries

-- ----------------------------
-- Table structure for bookings
-- ----------------------------
DROP TABLE IF EXISTS `bookings`;
CREATE TABLE "bookings" (
  "id" int NOT NULL AUTO_INCREMENT,
  "user_id" int NOT NULL,
  "tour_id" int NOT NULL,
  "booking_date" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "status" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING',
  "payment_status" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING',
  "refund_status" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "refund_transaction_id" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY ("id"),
  KEY "user_id" ("user_id"),
  KEY "tour_id" ("tour_id"),
  CONSTRAINT "bookings_ibfk_1" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  CONSTRAINT "bookings_ibfk_2" FOREIGN KEY ("tour_id") REFERENCES "tours" ("id") ON DELETE CASCADE
);

-- Records of bookings

-- ----------------------------
-- Table structure for booking_passengers
-- ----------------------------
DROP TABLE IF EXISTS `booking_passengers`;
CREATE TABLE "booking_passengers" (
  "id" int NOT NULL AUTO_INCREMENT,
  "booking_id" int NOT NULL,
  "full_name" varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  "gender" varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'Nam',
  "birth_date" date DEFAULT NULL,
  "id_card" varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "phone" varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "checked_in" tinyint(1) DEFAULT '0',
  "checked_in_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  KEY "idx_booking_pax" ("booking_id"),
  CONSTRAINT "booking_passengers_ibfk_1" FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE
);

-- Records of booking_passengers

-- ----------------------------
-- Table structure for tour_incidents
-- ----------------------------
DROP TABLE IF EXISTS `tour_incidents`;
CREATE TABLE "tour_incidents" (
  "id" int NOT NULL AUTO_INCREMENT,
  "tour_id" int NOT NULL,
  "reported_by" int NOT NULL,
  "incident_type" varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  "description" text COLLATE utf8mb4_unicode_ci NOT NULL,
  "severity" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'MEDIUM',
  "status" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'OPEN',
  "resolution" text COLLATE utf8mb4_unicode_ci,
  "reported_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "resolved_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  KEY "tour_id" ("tour_id"),
  KEY "reported_by" ("reported_by"),
  CONSTRAINT "tour_incidents_ibfk_1" FOREIGN KEY ("tour_id") REFERENCES "tours" ("id") ON DELETE CASCADE,
  CONSTRAINT "tour_incidents_ibfk_2" FOREIGN KEY ("reported_by") REFERENCES "users" ("id") ON DELETE CASCADE
);

-- Records of tour_incidents

-- ----------------------------
-- Table structure for contracts
-- ----------------------------
DROP TABLE IF EXISTS `contracts`;
CREATE TABLE "contracts" (
  "id" int NOT NULL AUTO_INCREMENT,
  "booking_id" int NOT NULL,
  "contract_code" varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  "total_amount" double NOT NULL,
  "status" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE',
  "terms_content" text COLLATE utf8mb4_unicode_ci,
  "qr_code_data" varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "signed_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE KEY "booking_id" ("booking_id"),
  UNIQUE KEY "contract_code" ("contract_code"),
  CONSTRAINT "contracts_ibfk_1" FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE
);

-- Records of contracts

-- ----------------------------
-- Table structure for coupons
-- ----------------------------
DROP TABLE IF EXISTS `coupons`;
CREATE TABLE "coupons" (
  "id" int NOT NULL AUTO_INCREMENT,
  "code" varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  "discount_type" varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PERCENT',
  "discount_value" double NOT NULL,
  "min_order_amount" double DEFAULT '0',
  "max_discount_amount" double DEFAULT '0',
  "expiry_date" date NOT NULL,
  "max_usage" int DEFAULT '100',
  "used_count" int DEFAULT '0',
  "active" tinyint(1) DEFAULT '1',
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "applicable_tour_id" int DEFAULT NULL,
  PRIMARY KEY ("id"),
  UNIQUE KEY "code" ("code"),
  KEY "fk_coupons_tour" ("applicable_tour_id"),
  CONSTRAINT "fk_coupons_tour" FOREIGN KEY ("applicable_tour_id") REFERENCES "tours" ("id") ON DELETE SET NULL
);

