  PRIMARY KEY ("setting_key")
);

-- Records of system_settings

-- ----------------------------
-- Table structure for audit_logs
-- ----------------------------
DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE "audit_logs" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "user_id" int NOT NULL,
  "booking_id" int DEFAULT NULL,
  "action" varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  "old_status" varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  "new_status" varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  "ip_address" varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "user_role" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'USER',
  "target_table" varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'bookings',
  "target_id" int DEFAULT '0',
  "old_value" text COLLATE utf8mb4_unicode_ci,
  "new_value" text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY ("id"),
  KEY "user_id" ("user_id"),
  KEY "booking_id" ("booking_id"),
  CONSTRAINT "audit_logs_ibfk_1" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  CONSTRAINT "audit_logs_ibfk_2" FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE
);

-- Records of audit_logs

-- ----------------------------
-- Table structure for login_history
-- ----------------------------
DROP TABLE IF EXISTS `login_history`;
CREATE TABLE "login_history" (
  "id" bigint NOT NULL AUTO_INCREMENT,
