  "logged_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  KEY "idx_login_time" ("logged_at"),
  KEY "idx_login_status" ("status")
);

-- Records of login_history

