INSERT INTO `tours` VALUES (1, 'Tour Khám Phá Đà Nẵng: Trọn Gói Khách Sạn 4-5 Sao (3N2Đ)', 'Chuyến du lịch khám phá Đà Nẵng xuất phát từ Hà Nội thời lượng 3N2Đ. Dịch vụ bao gồm khách sạn, xe đưa đón, hướng dẫn viên và bảo hiểm trọn gói.', 5500000.0, 6200000.0, 20, '2026-09-01', 'https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=1200&q=80', 'Hà Nội', 'Đà Nẵng', '3N2Đ', '2026-08-31 17:00:00.0', 'Việt Nam', 'APPROVED', NULL),
(2, 'Tour Nghỉ Dưỡng Cao Cấp SaPa: Trải Nghiệm Ẩm Thực & Danh Thắng (4N3Đ)', 'Chuyến du lịch khám phá SaPa xuất phát từ TP. Hồ Chí Minh thời lượng 4N3Đ. Dịch vụ bao gồm khách sạn, xe đưa đón, hướng dẫn viên và bảo hiểm trọn gói.', 2590000.0, 2990000.0, 13, '2026-09-15', 'https://images.unsplash.com/photo-1570366583862-f91883984fde?auto=format&fit=crop&w=1200&q=85', 'TP. Hồ Chí Minh', 'SaPa', '4N3Đ', '2026-09-18 09:01:10.0', 'Việt Nam', 'APPROVED', NULL),
(3, 'Tour Du Lịch Phú Quốc - Hành Trình Di Sản & Văn Hóa (2N1Đ)', 'Chuyến du lịch khám phá Phú Quốc xuất phát từ Đà Nẵng thời lượng 2N1Đ. Dịch vụ bao gồm khách sạn, xe đưa đón, hướng dẫn viên và bảo hiểm trọn gói.', 6800000.0, 0.0, 10, '2026-10-05', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=80', 'Đà Nẵng', 'Phú Quốc', '2N1Đ', NULL, 'Việt Nam', 'APPROVED', NULL),
(5, 'Tour Khám Phá Hạ Long: Trọn Gói Khách Sạn 4-5 Sao (5N4Đ)', 'Chuyến du lịch khám phá Hạ Long xuất phát từ Cần Thơ thời lượng 5N4Đ. Dịch vụ bao gồm khách sạn, xe đưa đón, hướng dẫn viên và bảo hiểm trọn gói.', 1.1E7, 1.3E7, 20, '2027-12-17', 'https://cdn.getyourguide.com/img/location/58c9219a7a849.jpeg/88.jpg', 'Cần Thơ', 'Hạ Long', '5N4Đ', '2026-09-18 09:01:10.0', 'Việt Nam', 'APPROVED', NULL),
(6, 'Tour Nghỉ Dưỡng Cao Cấp Ninh Bình: Trải Nghiệm Ẩm Thực & Danh Thắng (6N5Đ)', 'Chuyến du lịch khám phá Ninh Bình xuất phát từ Hải Phòng thời lượng 6N5Đ. Dịch vụ bao gồm khách sạn, xe đưa đón, hướng dẫn viên và bảo hiểm trọn gói.', 3290000.0, 3890000.0, 18, '2026-09-20', 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=1200&q=80', 'Hải Phòng', 'Ninh Bình', '6N5Đ', '2026-09-18 09:01:10.0', 'Việt Nam', 'APPROVED', NULL),
(7, 'Tour Du Lịch Hà Giang - Hành Trình Di Sản & Văn Hóa (3N2Đ)', 'Chuyến du lịch khám phá Hà Giang xuất phát từ Hà Nội thời lượng 3N2Đ. Dịch vụ bao gồm khách sạn, xe đưa đón, hướng dẫn viên và bảo hiểm trọn gói.', 3850000.0, 4500000.0, 14, '2026-09-25', 'https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=1200&q=80', 'Hà Nội', 'Hà Giang', '3N2Đ', '2026-09-18 09:01:10.0', 'Việt Nam', 'APPROVED', NULL),
